// 상장관련공통함수
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd3);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd4);
        rdo_ISUR_CD.setValue("0");
        rdo_ISUR_CD2.setValue("0");
        rdo_ISUR_CD3.setValue("0");
        rdo_ISUR_CD4.setValue("0");
        await scwin.getIsurcode();
        img_Elwlist.setSelectedTabIndex(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41110.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

