/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41110.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
        dts.setRowPosition(rowcount, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41110.dts_OnLoadCompleted" });
    }
};

