/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (rdo_ISUR_CD.getValue() === "0") {
            await $c.win.alert("발행사 나 LP 항목을 선택하십시요.");
            rdo_ISUR_CD.focus();
            return true;
        }
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            await $c.win.alert("발행사 나 LP 회사를 선택하십시요.");
            cmb_ISUR_CD.focus();
            return true;
        }
        // 기 저장된 회사가 있는지 체크
        if (dts.getRowPosition() !== 0) {
            await $c.win.alert("이미 저장된 회사입니다.");
            // cmb_ISUR_CD.focus();
            return true;
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41110.img_Regist_onclick" });
    }
};

