    try {
        $c.stf.doLogSave("ULDSTF41110.xml", SCREN_PROCS_TP_CD_07);
        if (dts.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "ELW 업무 담당자", type: "8"});
