/**
 * @method
 * @name grd_OnDblClick
 * @description grd 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_OnDblClick = async function(row, colid) {
    try {
        scwin.click_BYCORP_CHRG_BZ_TP_CD = dts.getCellData(row, 'BYCORP_CHRG_BZ_TP_CD');
        scwin.click_INVSTCOM_BZ_TP_CD = dts.getCellData(row, 'INVSTCOM_BZ_TP_CD');
        scwin.click_ISUR_CD = dts.getCellData(row, 'ISUR_CD');
        scwin.click_COM_ABBRV = dts.getCellData(row, 'COM_ABBRV');
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41110.grd_OnDblClick" });
    }
};

