 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_ISUR_CD_onselchange = async function() {
    try {
        if (rdo_ISUR_CD.getValue() === "0") cmb_ISUR_CD.ComboDataID = "dts_ElwInstLP";

        else if (rdo_ISUR_CD.getValue() === "1") cmb_ISUR_CD.ComboDataID = "dts_ElwInst";

        else if (rdo_ISUR_CD.getValue() === "2") cmb_ISUR_CD.ComboDataID = "dts_LpMbrNo";
