    url += "?SCREN_ID=" + "ULDSTF41110.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ELW_ETF_COM_CONTACT_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwetf.comcontact.select.listSearch" + "&{P}param01=3" + "&{P}param02=" + rdo_ISUR_CD.getValue() + // 법인코드
        "&{P}param03=" + rdo_ISUR_CD.getValue() + // 법인코드
        "&{P}param04=" + cmb_ISUR_CD.BindColVal + // 시작일자
        "&{P}param05=" + cmb_ISUR_CD.BindColVal; // 시작일자

    const sbmOptions = {
        id : "sbm_dts",
        action : "/listingCommon.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

