/**
 * @method
 * @name getIsurcode
 * @description elw발행사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsurcode = async function() {
    // elw발행사
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // etn발행사
    const sbmOptions2 = {
        id : "sbm_dts_EtnInst",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_EtnInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // dts_LpMbrNo.DataID = "/CodeAction.do?method=listLeadCom&For=R";
    // dts_LpMbrNo.Reset();
    await scwin.getElwLpMbrNoCd(); // 현재 상장관련있는 LP
    await scwin.getElwInstLpMbrNoCd(); // 발행사 및 현재 상장관련있는 LP
    await scwin.getEtnInstLpMbrNoCd(); // ETN발행사 및 현재 상장관련 있는 LP
    await scwin.getEtfTrstCom3Cd(); // etf 현재 상장관련있는운용사
    await scwin.getEtfTrstComLP3Cd(); // etf 운용사/LP 모두
    await scwin.getPfTrstCom4Cd(); // pf 현재 상장관련있는운용사
    await scwin.getPfTrstComLP4Cd(); // pf 운용사/LP 모두

    // CopyDataSet( dts_ElwInst , dts_ElwInst2) ;
    // cmb_ISUR_CD2.index =0;

    // CopyDataSet( dts_ElwInst , dts_ElwInst3) ;
    // cmb_ISUR_CD3.index =0;
    $c.stf.copyDataSet(dts_LpMbrNo, dts_LpMbrNo2);
    $c.stf.copyDataSet(dts_LpMbrNo, dts_LpMbrNo3);
    $c.stf.copyDataSet(dts_LpMbrNo, dts_LpMbrNo4);
    cmb_ISUR_CD.setSelectedIndex(0);
    cmb_ISUR_CD2.setSelectedIndex(0);
    cmb_ISUR_CD3.setSelectedIndex(0);
    cmb_ISUR_CD4.setSelectedIndex(0);
};

