/**
 * @method
 * @name newpreCreateFrame
 * @description newpre Create Frame 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function() {
    const options = {
        id: "ULDSTF41111",
        title: "ELW/ETN/ETF/상장형 수익증권 업무담당자 관리",
        type: "browserPopup",
        width: "920px",
        height: "325px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../lstmgt/ULDSTF41111.gfm", options);
    await scwin.search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};

